-- Workbench editing for all 38 lookup vocabularies. Run after the combined thesauri SQL.
-- Existing IDs, hierarchy, canonical record values and raw unclassified notes are retained.
BEGIN;
SET LOCAL lock_timeout='60s';
SET LOCAL statement_timeout='180s';
CREATE SCHEMA IF NOT EXISTS vocab_workbench;
CREATE TABLE IF NOT EXISTS vocab_workbench.editor_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vocab_workbench.editor_registry (vocabulary_code text PRIMARY KEY, title text NOT NULL, source_view text NOT NULL, concept_uri_base text NOT NULL);
CREATE TABLE IF NOT EXISTS vocab_workbench.canonical_keys (vocabulary_code text NOT NULL,concept_id text NOT NULL,value text,PRIMARY KEY(vocabulary_code,concept_id));
CREATE TABLE IF NOT EXISTS vocab_workbench.display_labels (vocabulary_code text NOT NULL,concept_id text NOT NULL,lang text NOT NULL,label text NOT NULL,PRIMARY KEY(vocabulary_code,concept_id,lang));
CREATE TABLE IF NOT EXISTS vocab_workbench.editor_texts (
 vocabulary_code text NOT NULL,concept_id text NOT NULL DEFAULT '',field text NOT NULL CHECK(field IN ('alternative','definition','scopeNote','description','editorial')),
 lang text NOT NULL CHECK(lang IN ('en','ru','zh','kk','ky','tg','tk','uz')),texts jsonb NOT NULL CHECK(jsonb_typeof(texts)='array'),
 PRIMARY KEY(vocabulary_code,concept_id,field,lang));
CREATE TABLE IF NOT EXISTS vocab_workbench.editor_revisions (
 revision_id bigserial PRIMARY KEY,vocabulary_code text NOT NULL,concept_id text NOT NULL,field text NOT NULL,lang text NOT NULL,
 old_values jsonb NOT NULL,new_values jsonb NOT NULL,changed_by_user_id text,changed_by_username text NOT NULL,changed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS editor_revisions_vocabulary_idx ON vocab_workbench.editor_revisions(vocabulary_code,revision_id);
CREATE TABLE IF NOT EXISTS vocab_workbench.editor_publications (
 publication_id bigserial PRIMARY KEY,vocabulary_code text NOT NULL,status text NOT NULL CHECK(status IN ('running','success','failed')),
 started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,through_revision bigint NOT NULL DEFAULT 0,
 started_by_username text NOT NULL,report_path text,error text);
CREATE UNIQUE INDEX IF NOT EXISTS editor_one_publication ON vocab_workbench.editor_publications((true)) WHERE status='running';
CREATE TABLE IF NOT EXISTS vocab_workbench.editor_alignments (
 alignment_id bigserial PRIMARY KEY,vocabulary_code text NOT NULL,source_concept_id text NOT NULL,
 target_uri text NOT NULL,target_label text NOT NULL,target_label_language text NOT NULL DEFAULT '',
 relation text NOT NULL CHECK(relation IN ('exactMatch','closeMatch','broadMatch','narrowMatch','relatedMatch')),
 status text NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed','accepted','rejected','deprecated')),
 evidence text NOT NULL DEFAULT '',candidate_snapshot jsonb NOT NULL,source_snapshot jsonb NOT NULL,search_text text NOT NULL DEFAULT '',
 proposed_by_user_id text,proposed_by_username text NOT NULL,reviewed_by_user_id text,reviewed_by_username text,
 reviewed_at timestamptz,review_note text,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS editor_alignment_live_pair ON vocab_workbench.editor_alignments(vocabulary_code,source_concept_id,target_uri) WHERE status IN ('proposed','accepted');
CREATE TABLE IF NOT EXISTS vocab_workbench.editor_alignment_events (
 event_id bigserial PRIMARY KEY,alignment_id bigint NOT NULL REFERENCES vocab_workbench.editor_alignments(alignment_id),action text NOT NULL,
 old_data jsonb,new_data jsonb NOT NULL,changed_by_username text NOT NULL,changed_at timestamptz NOT NULL DEFAULT now());
