 IF col.attname='canonical_value' THEN projection:=projection||format('CASE WHEN k.concept_id IS NOT NULL THEN k.value::%s ELSE s.%I END AS %I',col.typ,col.attname,col.attname);
 ELSE projection:=projection||format('s.%I',col.attname); END IF; END LOOP;
