-- Mirror existing Workbench roles; do not grant access to anonymous/public roles.
DO $permissions$
DECLARE r record; t record;
BEGIN
 FOR r IN SELECT DISTINCT grantee FROM information_schema.table_privileges WHERE table_schema='ui' AND table_name IN ('v_lkp_address_type','v_lkp_admin_type','v_lkp_countries','v_lkp_loc_acc_ass','v_lkp_classifications','v_lkp_designation_type','v_lkp_religion','v_lkp_actor_type','v_lkp_external_xref_types','v_lkp_beg_of_exist_type','v_lkp_content_types','v_lkp_copyright_status','v_lkp_dataset_type','v_lkp_description_type','v_lkp_digital_file_formats','v_lkp_end_of_exist_type','v_lkp_level','v_lkp_names_type','v_lkp_subjects','v_lkp_titles_type','v_lkp_threat_types','v_lkp_ground_truthing_priority','v_lkp_condition','v_lkp_condition_level','v_lkp_deterioration_cause','v_lkp_risk_level','v_lkp_anomaly_type','v_lkp_certainty','v_lkp_origin','v_lkp_geometry_qualifiers','v_lkp_cultural_periods_raw','v_lkp_colour','v_lkp_measurement_type','v_lkp_size_dimensions_original_material','v_lkp_unit_of_measurement','v_lkp_languages_abridged','v_lkp_scripts','v_lkp_writing_systems') AND privilege_type='SELECT' AND grantee<>'PUBLIC' LOOP
  EXECUTE format('GRANT USAGE ON SCHEMA vocab_workbench TO %I',r.grantee);
  EXECUTE format('GRANT SELECT ON vocab_workbench.canonical_keys,vocab_workbench.display_labels TO %I',r.grantee);
 END LOOP;
 FOR r IN SELECT DISTINCT grantee FROM information_schema.table_privileges WHERE table_schema='public' AND table_name='labels_curated' AND privilege_type IN ('UPDATE','INSERT') AND grantee<>'PUBLIC' LOOP
  EXECUTE format('GRANT USAGE ON SCHEMA vocab_workbench TO %I',r.grantee);
  FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='vocab_workbench' AND tablename IN ('editor_registry','canonical_keys','display_labels','editor_texts','editor_revisions','editor_publications','editor_alignments','editor_alignment_events','editor_migrations') LOOP
   EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON vocab_workbench.%I TO %I',t.tablename,r.grantee);
  END LOOP;
  FOR t IN SELECT sequencename FROM pg_sequences WHERE schemaname='vocab_workbench' AND sequencename LIKE 'editor_%' LOOP
   EXECUTE format('GRANT USAGE,SELECT ON SEQUENCE vocab_workbench.%I TO %I',t.sequencename,r.grantee);
  END LOOP;
 EXECUTE format('GRANT SELECT ON "public"."ThsAddressType" TO %I',r.grantee);
